"use client";

import { useState, type FormEvent } from "react";

interface ScenarioSelectorProps {
  onSelect: (scenario: string, topic: string) => void;
  isLoading: boolean;
}

const SCENARIOS = [
  "casual_conversation",
  "job_interview",
  "restaurant_ordering",
  "travel_planning",
  "tech_discussion",
];

export function ScenarioSelector({ onSelect, isLoading }: ScenarioSelectorProps) {
  const [scenario, setScenario] = useState(SCENARIOS[0]);
  const [topic, setTopic] = useState("");

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!topic.trim()) return;
    onSelect(scenario, topic.trim());
  };

  return (
    <div className="flex items-center justify-center min-h-screen p-4">
      <form onSubmit={handleSubmit} className="w-full max-w-md space-y-5">
        <div className="text-center space-y-1">
          <h1 className="text-2xl font-semibold text-zinc-100">EmilyTalks</h1>
          <p className="text-sm text-zinc-400">Choose a scenario to start practicing</p>
        </div>

        <div className="space-y-2">
          <label className="text-sm text-zinc-300">Scenario</label>
          <select
            value={scenario}
            onChange={(e) => setScenario(e.target.value)}
            className="w-full bg-zinc-800 text-zinc-100 rounded-xl px-4 py-2.5 text-sm
              outline-none focus:ring-2 focus:ring-blue-500/50"
          >
            {SCENARIOS.map((s) => (
              <option key={s} value={s}>
                {s.replace(/_/g, " ")}
              </option>
            ))}
          </select>
        </div>

        <div className="space-y-2">
          <label className="text-sm text-zinc-300">Topic</label>
          <input
            type="text"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="e.g., Ordering coffee at Starbucks"
            className="w-full bg-zinc-800 text-zinc-100 rounded-xl px-4 py-2.5 text-sm
              placeholder:text-zinc-500 outline-none focus:ring-2 focus:ring-blue-500/50"
          />
        </div>

        <button
          type="submit"
          disabled={!topic.trim() || isLoading}
          className="w-full bg-blue-600 text-white rounded-xl py-2.5 text-sm font-medium
            hover:bg-blue-500 disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
        >
          {isLoading ? "Preparing..." : "Start Conversation"}
        </button>
      </form>
    </div>
  );
}
