"use client";

import { useState, useRef, useEffect } from "react";
import { ChatMessage } from "@/components/ChatMessage";
import { ChatInput } from "@/components/ChatInput";
import { ScenarioSelector } from "@/components/ScenarioSelector";
import { useStreamChat } from "@/hooks/useStreamChat";
import { prepareAgent, resetAgent } from "@/lib/api";

export default function ChatPage() {
  const [isReady, setIsReady] = useState(false);
  const [isPreparing, setIsPreparing] = useState(false);
  const { messages, isStreaming, sendMessage, clearMessages } = useStreamChat();
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSelectScenario = async (scenario: string, topic: string) => {
    setIsPreparing(true);
    try {
      await prepareAgent({ scenario, topic });
      setIsReady(true);
    } catch {
      console.error("Failed to prepare agent");
    } finally {
      setIsPreparing(false);
    }
  };

  const handleReset = async () => {
    await resetAgent();
    clearMessages();
    setIsReady(false);
  };

  if (!isReady) {
    return <ScenarioSelector onSelect={handleSelectScenario} isLoading={isPreparing} />;
  }

  return (
    <div className="flex flex-col h-screen max-w-2xl mx-auto">
      <header className="flex items-center justify-between px-4 py-3 border-b border-zinc-800">
        <div>
          <h1 className="text-lg font-semibold">Emily</h1>
          <p className="text-xs text-zinc-400">
            {isStreaming ? "typing..." : "online"}
          </p>
        </div>
        <button
          onClick={handleReset}
          className="text-xs text-zinc-400 hover:text-zinc-200 transition-colors"
        >
          New conversation
        </button>
      </header>

      <div className="flex-1 overflow-y-auto px-4 py-4">
        {messages.length === 0 && (
          <p className="text-center text-zinc-500 text-sm mt-8">
            Say something to start the conversation
          </p>
        )}
        {messages.map((msg) => (
          <ChatMessage key={msg.id} message={msg} />
        ))}
        <div ref={bottomRef} />
      </div>

      <ChatInput onSend={sendMessage} disabled={isStreaming} />
    </div>
  );
}
